$('catalogueClose').onclick=()=>{catalogueOpen=false;$('catalogue').classList.add('hidden')};$('catalogueSearch').oninput=()=>{catalogueMode='samples';renderCatalogue()};$('sampleMode').onclick=()=>{catalogueMode='samples';renderCatalogue()};$('pageMode').onclick=()=>{catalogueMode='pages';renderCatalogue()};
async function loadCatalogue(){try{const response=await fetch('./catalogue/catalogue.json');if(!response.ok)throw Error('Catalogue unavailable');const result=await response.json();catalogueData=result.samples;catalogueReady=true;update();if(catalogueOpen)renderCatalogue()}catch(e){$('catalogueError').textContent='Catalogue could not load. Refresh to try again.'}}loadCatalogue();

function exportQuotationPDF(){$('sheet').close();return showQuotationPDF({items:data,houses,location:quoteLocation,option:project.option,price,included:i=>get(i).included,finish:finishLabel})}
$('printSelections').onclick=exportQuotationPDF;

$('showProductDetails').onclick=()=>$('productDetails').showModal();$('closeProductDetails').onclick=()=>$('productDetails').close();$('detailsExclude').onclick=()=>{const i=data.find(i=>i.id===selected);state.choices[i.id]={...get(i),included:!get(i).included};save();update()};

function persistGuide(){try{sessionStorage.setItem('olive-guide-session',JSON.stringify({entered:experienceEntered,dismissed:!guideActive,completed:guideStage==='done'}))}catch{}}
function renderGuide(){const steps={select:['1','Tap a cabinet to view it','Tap a unit in the 3D room, or choose its name below. It will open in its own product view.','stage'],change:['2','Tap a mica sample to change the colour','Swipe the mica samples below the model and tap one. Choose Fronts, Sides or Both above.','catalogueView'],open:['3','Tap a shutter or drawer to open it','Tap the door or drawer on the model. Tap it again to close. You can also use Open all.','stage'],return:['4','Untick Product view to see the whole room','Use the highlighted tick at the top to return to all the room’s items.','focusItem'],done:['✓','You’re ready to explore','Try other rooms, finishes and units. Use Details for specifications and Review selections for your quotation.',null]};['stage','catalogueView','focusItem'].forEach(id=>$(id).classList.remove('guide-target'));$('guideBar').classList.toggle('hidden',!guideActive||!experienceEntered||guideStage==='welcome');if(!guideActive||!experienceEntered||guideStage==='welcome')return;const step=steps[guideStage]||steps.select;$('guideStep').textContent=step[0];$('guideTitle').textContent=step[1];$('guideText').textContent=step[2];if(step[3])$(step[3]).classList.add('guide-target')}
function guideEvent(event){if(!experienceEntered)return;if(event==='finish')guideChanged=true;if(event==='open')guideOpened=true;if(event==='room'){if(guideStage==='return')guideStage='done';else if(guideStage!=='done')guideStage='select'}else if(event==='selected'||event==='finish'||event==='open'){if(guideStage!=='done'){guideStage=!guideChanged?'change':!guideOpened&&engine?.canOpen(selected)?'open':'return'}}renderGuide();persistGuide()}
function enterExperience(){if(['kitchen','master','bedroom2','bedroom3','hall'].includes(activeRoom)){window.location.assign(roomViewUrl(activeRoom));return;}document.body.classList.remove('show-welcome');$('welcome').classList.add('hidden');$('roomHeading').textContent=roomName+' · explore your design';$('introText').textContent='Demo model · your supplied room model will replace this arrangement. Drag to rotate; tap a unit to explore.';if(experienceEntered){renderGuide();return;}experienceEntered=true;document.body.classList.remove('show-welcome');$('welcome').classList.add('hidden');createExperience();guideActive=!guideSession.dismissed;guideStage=guideSession.completed?'done':'select';renderGuide();persistGuide()}
$('enter3D').onclick=()=>window.location.assign('./rooms.html');$('hideGuide').onclick=()=>{guideActive=false;renderGuide();persistGuide()};$('showHelp').onclick=()=>{if(!experienceEntered)enterExperience();guideActive=true;guideChanged=false;guideOpened=false;guideStage=engine?.isFocused()?'change':'select';renderGuide();persistGuide()};if(new URLSearchParams(window.location.search).get('view')==='3d')enterExperience();else{$('roomHeading').textContent='Your interior quotation'}

function renderOpeningQuote(){if(!$('openingQuoteRows'))return;$('openingQuoteSelect').value=String(project.option);
$('openingQuoteRows').innerHTML=houses.map(house=>{const list=data.filter(i=>i.house===house.key);const roomKeys=[...new Set(list.map(i=>i.room))];const subtotal=list.reduce((v,i)=>v+(get(i).included?price(i):0),0);return `<tr class="house-heading"><th colspan="6">${escapeHtml(house.name)}</th></tr>`+roomKeys.map(key=>{const entries=list.filter(i=>i.room===key);const roomTotal=entries.reduce((sum,i)=>sum+(get(i).included?price(i):0),0);return `<tr class="room-heading"><td colspan="6">${escapeHtml(quoteRoomName(entries[0]))}</td></tr>`+entries.map(i=>`<tr class="${get(i).included?'':'excluded-row'}"><td><strong>${i.id}. ${escapeHtml(i.name)}</strong><small>${escapeHtml(i.spec)} · Factory finishing and 2 mm edge banding on applicable board edges.</small><small>${escapeHtml(finishLabel(i))}</small></td><td>${escapeHtml(i.size)}</td><td>${i.area}</td><td>${currency(i.rate*quoteFactors[project.option])}</td><td>${currency(price(i))}</td><td><button type="button" data-quote-item="${i.id}" aria-pressed="${get(i).included}">${get(i).included?'✓ Included · exclude':i.id===7?'+ Include optional item':'+ Include item'}</button></td></tr>`).join('')+`<tr class="room-subtotal"><th colspan="4">${escapeHtml(quoteRoomName(entries[0]))} total</th><td colspan="2"><strong>${currency(roomTotal)}</strong></td></tr>`}).join('')+`<tr class="house-subtotal"><th colspan="4">${escapeHtml(house.name)} · HOUSE GRAND TOTAL</th><td colspan="2"><strong>${currency(subtotal)}</strong></td></tr>`}).join('');
$('openingTotal').textContent=currency(total());const excluded=data.filter(i=>!get(i).included);$('openingExcluded').textContent=excluded.length+' excluded / optional item'+(excluded.length===1?'':'s')+' · '+currency(excluded.reduce((v,i)=>v+price(i),0))+' not included in the selected total.';if(!$('openingFloorPlan').innerHTML)$('openingFloorPlan').innerHTML=openingPlanSVG()}
$('openingQuoteRows').onclick=e=>{const button=e.target.closest('[data-quote-item]');if(!button)return;const item=data.find(i=>i.id===+button.dataset.quoteItem);if(!item)return;state.choices[item.id]={...get(item),included:!get(item).included};save();update()};

function openingPlanSVG(){const P=(x,y,z=0)=>[380+(x-y)*42,68+(x+y)*21-z*25];const pts=a=>a.map(p=>P(...p).join(',')).join(' ');const blocks=[['kitchen',0,0,3.2,2.5,'#e2e9d6'],['hall',3.2,0,3.8,2.5,'#e8dfcd'],['master',0,2.5,2.7,3,'#d4e0d0'],['bedroom2',2.7,2.5,2.3,3,'#e5ddcf'],['bedroom3',5,2.5,2,3,'#dce5d4']];return `<svg viewBox="60 10 650 390" role="img" aria-label="Illustrative 3D floor-plan preview with five selectable rooms"><ellipse cx="390" cy="325" rx="235" ry="27" fill="#dbe1d0"/>`+blocks.map(([key,x,y,w,h,col])=>{const cx=x+w/2,cy=y+h/2,label=P(cx,cy,.03),name=rooms.find(r=>r.key===key).name;return `<a href="${roomViewUrl(key)}" aria-label="Explore ${name} in 3D"><polygon points="${pts([[x,y,0],[x+w,y,0],[x+w,y,.25],[x,y,.25]])}" fill="#9aa98c"/><polygon points="${pts([[x+w,y,0],[x+w,y+h,0],[x+w,y+h,.25],[x+w,y,.25]])}" fill="#b5bea5"/><polygon class="room-surface" points="${pts([[x,y,.25],[x+w,y,.25],[x+w,y+h,.25],[x,y+h,.25]])}" fill="${col}" stroke="#718367" stroke-width="1.5"/><polygon points="${pts([[x,y,.25],[x+w,y,.25],[x+w,y,1.15],[x,y,1.15]])}" fill="#fbfcf6" stroke="#aeb99f"/><polygon points="${pts([[x,y,.25],[x,y+h,.25],[x,y+h,1.15],[x,y,1.15]])}" fill="#d6dec9" stroke="#aeb99f"/><text x="${label[0]}" y="${label[1]}" text-anchor="middle" font-size="12" font-weight="600" fill="#29452f">${name}</text><text x="${label[0]}" y="${label[1]+17}" text-anchor="middle" font-size="9" fill="#607254">${['kitchen','master','bedroom2','bedroom3','hall'].includes(key)?'Your model':'Demo model'} ↗</text></a>`}).join('')+`<text x="390" y="374" text-anchor="middle" font-size="10" fill="#718168">Sample room arrangement · actual site floor plan pending</text></svg>`}
$('openingQuoteSelect').onchange=e=>$('quoteSelect').onchange(e);$('openingPrint').onclick=exportQuotationPDF;$('backToQuote').onclick=()=>{engine?.restoreRoom();document.body.classList.add('show-welcome');$('welcome').classList.remove('hidden');$('roomHeading').textContent='Your interior quotation';$('introText').textContent='Complete item pricing, with an optional interactive 3D preview.';renderOpeningQuote();window.scrollTo?.({top:0,behavior:'smooth'})};renderOpeningQuote();
